// ---------------------------------------------------------------------------
// POST /repairs/:id/complete — Complete repair with payment (atomic transaction)
//
// Accepts single or split payment methods. Atomically:
//   1. Validates repair is in 'ready' status
//   2. Computes total from line items and validates payment amounts match
//   3. Checks stock availability for all parts used
//   4. Creates linked Sale (sourceType='repair') with sale + line items
//   5. Creates payment records and allocations
//   6. Deducts stock via movements (reason='repair_use')
//   7. Marks repair as completed with completedAt timestamp
// All-or-nothing: any failure rolls back everything.
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/complete', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    // Validate that payments array is provided and non-empty
    if (!input?.payments || !Array.isArray(input.payments) || input.payments.length === 0) {
      return c.json({ error: 'At least one payment method is required', code: 'VALIDATION_ERROR' }, 400)
    }

    // Validate each payment has method and positive amount
    for (const pay of input.payments) {
      if (!pay.method || !['cash', 'card'].includes(pay.method)) {
        return c.json({ error: `Invalid payment method: ${pay?.method}`, code: 'VALIDATION_ERROR' }, 400)
      }
      if (typeof pay.amount !== 'number' || pay.amount <= 0) {
        return c.json({ error: 'Payment amount must be a positive number', code: 'VALIDATION_ERROR' }, 400)
      }
    }

    const result = await completeRepairPayment(id, { payments: input.payments })
    return c.json(result, 200)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Payment completion failed'
    const name = (err as { name?: string }).name || ''

    // Map specific errors to appropriate HTTP status codes
    if (name === 'RepairNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }
    if (name === 'RepairNotReadyError') {
      return c.json({ error: message, code: 'INVALID_STATUS' }, 409)
    }
    if (name === 'PaymentMismatchError') {
      return c.json({ error: message, code: 'PAYMENT_MISMATCH' }, 422)
    }
    if (name === 'InsufficientStockForRepairError') {
      const shortfalls = (err as { shortfalls?: unknown[] }).shortfalls
      return c.json(
        { error: message, code: 'INSUFFICIENT_STOCK', shortfalls },
        422
      )
    }

    return c.json({ error: message, code: name || 'INTERNAL_ERROR' }, 500)
  }
})

export default repairsRoutes

import { Hono } from 'hono'
import {
  createDirectSale,
  voidSale,
