import { db } from '@/db/index.js'
import {
  quotes,
  quoteLineItems,
  parts,
  laborServices,
  bicycles,
  vatRates,
  sequences,
} from '@/db/schema.js'
import { eq, sql, and, isNull, desc, asc } from 'drizzle-orm'

// ---------------------------------------------------------------------------
// Custom Error Classes
// ---------------------------------------------------------------------------

/** Thrown when a quote is not found. */
export class QuoteNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Quote not found: ${id}`)
    this.name = 'QuoteNotFoundError'
  }
}

/** Thrown when an operation requires draft status but the quote is not in draft state. */
export class QuoteNotDraftError extends Error {
  constructor(public readonly id: string, public readonly currentStatus: string) {
    super(`Quote ${id} is not in draft state (current: ${currentStatus}). Only draft quotes can be modified.`)
    this.name = 'QuoteNotDraftError'
  }
}

/** Thrown when a quote line item is not found. */
export class QuoteLineItemNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Quote line item not found: ${id}`)
    this.name = 'QuoteLineItemNotFoundError'
  }
}

// ---------------------------------------------------------------------------
// Types — request/response shapes
// ---------------------------------------------------------------------------

export type QuoteStatus = 'draft' | 'sent' | 'converted' | 'rejected'

export interface QuoteListResult {
  quotes: Array<{
    id: string
    quoteNumber: string
    customerId: string | null
    status: QuoteStatus
    notes: string | null
    createdAt: number
    updatedAt: number
  }>
  total: number
}

export interface QuoteDetail {
  id: string
  quoteNumber: string
  customerId: string | null
  status: QuoteStatus
  notes: string | null
  lineItems: QuoteLineItem[]
  createdAt: number
  updatedAt: number
}

export interface QuoteLineItem {
  id: string
  quoteId: string
  lineType: 'part' | 'labor' | 'bicycle'
  partId: string | null
  laborServiceId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
  bicycleId: string | null
  bicycleBrand: string | null
  bicycleModel: string | null
  bicycleYear: number | null
  bicycleColor: string | null
  bicycleFrameSize: string | null
  createdAt: number
}

// ---------------------------------------------------------------------------
// Helper — Calculate line item totals from unit price, quantity, discount
// ---------------------------------------------------------------------------

function calculateLineTotals(
  unitPriceNet: number,
  quantity: number,
  vatRateId: string,
  discountPercent: number | null,
): { lineTotalNet: number; lineTotalVat: number; lineTotalGross: number } {
  // Calculate net total (with optional per-line discount in basis points)
  const discountMultiplier = discountPercent !== null ? 1 - discountPercent / 10000 : 1
  const lineTotalNet = Math.round(unitPriceNet * quantity * discountMultiplier)

  // Fetch VAT rate from database to calculate tax
  return { lineTotalNet, lineTotalVat: 0, lineTotalGross: 0 } // Will be filled after DB lookup
}

// ---------------------------------------------------------------------------
// Helper — Get VAT rate for a given vatRateId
// ---------------------------------------------------------------------------

async function getVatRate(vatRateId: string): Promise<{ rate: number }> {
  const [rate] = await db.select({ rate: vatRates.rate }).from(vatRates).where(eq(vatRates.id, vatRateId))
  if (!rate) {
    throw new Error(`VAT rate not found: ${vatRateId}`)
  }
  return rate
}

// ---------------------------------------------------------------------------
// Helper — Generate quote number from sequence
// ---------------------------------------------------------------------------

async function generateQuoteNumber(): Promise<string> {
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, 'quote'))

  if (updateResult.changes === 0) {
    // Sequence doesn't exist yet — create it starting at 1
    await db.insert(sequences).values({ name: 'quote', currentValue: 1 })
  }

  const [seqRow] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, 'quote'))

  const seqNum = seqRow!.currentValue
  return `QT-${String(seqNum).padStart(4, '0')}`
}

// ---------------------------------------------------------------------------
// Helper — Enforce draft-only access on a quote
// ---------------------------------------------------------------------------

async function enforceDraftStatus(quoteId: string): Promise<void> {
  const [quote] = await db.select({ status: quotes.status }).from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  if (quote.status !== 'draft') {
    throw new QuoteNotDraftError(quoteId, quote.status)
  }
}

// ---------------------------------------------------------------------------
// Service Functions — Quote CRUD
// ---------------------------------------------------------------------------

/**
 * Create a new draft quote with auto-generated quote number.
 */
export async function createQuote(input: {
  customerId?: string | null
  notes?: string | null
}): Promise<QuoteDetail> {
  const quoteNumber = await generateQuoteNumber()
  const now = Date.now()

  const [inserted] = await db
    .insert(quotes)
    .values({
      id: crypto.randomUUID(),
      quoteNumber,
      customerId: input.customerId ?? null,
      status: 'draft',
      notes: input.notes ?? null,
      createdAt: new Date(now),
      updatedAt: new Date(now),
    })
    .returning()

  return getQuoteDetail(inserted.id)
}

/**
 * List quotes with optional status filter. Returns newest first.
 */
export async function getQuotesList(statusFilter?: string): Promise<QuoteListResult> {
  const whereClause = statusFilter ? and(eq(quotes.status, statusFilter)) : undefined

  const quoteRows = await db
    .select({
      id: quotes.id,
      quoteNumber: quotes.quoteNumber,
      customerId: quotes.customerId,
      status: quotes.status,
      notes: quotes.notes,
      createdAt: quotes.createdAt,
      updatedAt: quotes.updatedAt,
    })
    .from(quotes)
    .where(whereClause)
    .orderBy(desc(quotes.createdAt))

  const total = quoteRows.length

  return {
    quotes: quoteRows.map(row => ({
      ...row,
      createdAt: row.createdAt.getTime(),
      updatedAt: row.updatedAt.getTime(),
    })),
    total,
  }
}

/**
 * Get a single quote by ID with its line items.
 */
export async function getQuoteById(quoteId: string): Promise<QuoteDetail> {
  const [quote] = await db.select().from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  return getQuoteDetail(quoteId)
}

/**
 * Update draft-only fields on a quote (customerId, notes).
 */
export async function updateQuote(quoteId: string, input: {
  customerId?: string | null
  notes?: string | null
}): Promise<QuoteDetail> {
  // Enforce draft status before allowing updates
  await enforceDraftStatus(quoteId)

  const now = Date.now()
  const [updated] = await db
    .update(quotes)
    .set({
      ...(input.customerId !== undefined && { customerId: input.customerId }),
      ...(input.notes !== undefined && { notes: input.notes }),
      updatedAt: new Date(now),
    })
    .where(eq(quotes.id, quoteId))
    .returning()

  return getQuoteDetail(quoteId)
}

/**
 * Delete a draft quote and all its line items.
 */
export async function deleteQuote(quoteId: string): Promise<void> {
  // Enforce draft status before allowing deletion
  await enforceDraftStatus(quoteId)

  // Delete line items first (foreign key constraint)
  await db.delete(quoteLineItems).where(eq(quoteLineItems.quoteId, quoteId))

  // Delete the quote
  await db.delete(quotes).where(eq(quotes.id, quoteId))
}

// ---------------------------------------------------------------------------
// Service Functions — Quote Line Item CRUD
// ---------------------------------------------------------------------------

/**
 * Create a new line item for a quote. Validates draft status and calculates totals.
 */
export async function createQuoteLineItem(quoteId: string, input: {
  lineType: 'part' | 'labor' | 'bicycle'
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  // Bicycle fields (only for lineType === 'bicycle')
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}): Promise<QuoteLineItem> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  const now = Date.now()

  // Fetch VAT rate to calculate tax amounts
  const vatRate = await getVatRate(input.vatRateId)

  // Calculate line totals
  const discountMultiplier = input.discountPercent !== null ? 1 - input.discountPercent / 10000 : 1
  const lineTotalNet = Math.round(input.unitPriceNet * input.quantity * discountMultiplier)
  const lineTotalVat = Math.round(lineTotalNet * vatRate.rate / 10000)
  const lineTotalGross = lineTotalNet + lineTotalVat

  const [inserted] = await db
    .insert(quoteLineItems)
    .values({
      id: crypto.randomUUID(),
      quoteId,
      lineType: input.lineType,
      partId: input.partId ?? null,
      laborServiceId: input.laborServiceId ?? null,
      description: input.description,
      quantity: input.quantity,
      unitPriceNet: input.unitPriceNet,
      vatRateId: input.vatRateId,
      discountPercent: input.discountPercent ?? null,
      lineTotalNet,
      lineTotalVat,
      lineTotalGross,
      bicycleId: input.bicycleId ?? null,
      bicycleBrand: input.bicycleBrand ?? null,
      bicycleModel: input.bicycleModel ?? null,
      bicycleYear: input.bicycleYear ?? null,
      bicycleColor: input.bicycleColor ?? null,
      bicycleFrameSize: input.bicycleFrameSize ?? null,
      createdAt: new Date(now),
    })
    .returning()

  return {
    ...inserted,
    createdAt: inserted.createdAt.getTime(),
  } as QuoteLineItem
}

/**
 * Update an existing line item. Validates draft status on parent quote.
 */
export async function updateQuoteLineItem(quoteId: string, lineItemId: string, input: {
  description?: string
  quantity?: number
  unitPriceNet?: number
  vatRateId?: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  // Bicycle fields (only for lineType === 'bicycle')
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}): Promise<QuoteLineItem> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  // Fetch existing line item to get its type and current values for recalculation
  const [existing] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  if (!existing) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  // Verify the line item belongs to this quote
  if (existing.quoteId !== quoteId) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  const now = Date.now()

  // Build update set — only include fields that were provided
  const updateSet: Record<string, unknown> = { updatedAt: new Date(now) }

  if (input.description !== undefined) updateSet.description = input.description
  if (input.quantity !== undefined) updateSet.quantity = input.quantity
  if (input.unitPriceNet !== undefined) updateSet.unitPriceNet = input.unitPriceNet
  if (input.vatRateId !== undefined) {
    updateSet.vatRateId = input.vatRateId
    // Recalculate totals with new VAT rate
    const vatRate = await getVatRate(input.vatRateId)
    const discountMultiplier = input.discountPercent !== null && input.discountPercent !== existing.discountPercent
      ? 1 - (input.discountPercent ?? 0) / 10000
      : (existing.discountPercent !== null ? 1 - existing.discountPercent / 10000 : 1)
    const newUnitPrice = input.unitPriceNet ?? existing.unitPriceNet
    const newQuantity = input.quantity ?? existing.quantity
    updateSet.lineTotalNet = Math.round(newUnitPrice * newQuantity * discountMultiplier)
    updateSet.lineTotalVat = Math.round(updateSet.lineTotalNet * vatRate.rate / 10000)
    updateSet.lineTotalGross = (updateSet as any).lineTotalNet + (updateSet as any).lineTotalVat
  }
  if (input.discountPercent !== undefined) {
    // If VAT rate also changed, totals already calculated above; otherwise recalculate
    if (!input.vatRateId) {
      const vatRate = await getVatRate(existing.vatRateId)
      const discountMultiplier = input.discountPercent !== null ? 1 - input.discountPercent / 10000 : 1
      const newUnitPrice = input.unitPriceNet ?? existing.unitPriceNet
      const newQuantity = input.quantity ?? existing.quantity
      updateSet.lineTotalNet = Math.round(newUnitPrice * newQuantity * discountMultiplier)
      updateSet.lineTotalVat = Math.round((updateSet as any).lineTotalNet * vatRate.rate / 10000)
      updateSet.lineTotalGross = (updateSet as any).lineTotalNet + (updateSet as any).lineTotalVat
    }
    updateSet.discountPercent = input.discountPercent ?? null
  }

  // Type-specific fields
  if (input.partId !== undefined) updateSet.partId = input.partId
  if (input.laborServiceId !== undefined) updateSet.laborServiceId = input.laborServiceId
  if (input.bicycleId !== undefined) updateSet.bicycleId = input.bicycleId
  if (input.bicycleBrand !== undefined) updateSet.bicycleBrand = input.bicycleBrand
  if (input.bicycleModel !== undefined) updateSet.bicycleModel = input.bicycleModel
  if (input.bicycleYear !== undefined) updateSet.bicycleYear = input.bicycleYear
  if (input.bicycleColor !== undefined) updateSet.bicycleColor = input.bicycleColor
  if (input.bicycleFrameSize !== undefined) updateSet.bicycleFrameSize = input.bicycleFrameSize

  const [updated] = await db
    .update(quoteLineItems)
    .set(updateSet as any)
    .where(eq(quoteLineItems.id, lineItemId))
    .returning()

  return {
    ...updated,
    createdAt: updated.createdAt.getTime(),
  } as QuoteLineItem
}

/**
 * Delete a line item. Validates draft status on parent quote.
 */
export async function deleteQuoteLineItem(quoteId: string, lineItemId: string): Promise<void> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  const [existing] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  if (!existing) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  // Verify the line item belongs to this quote
  if (existing.quoteId !== quoteId) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  await db.delete(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))
}

// ---------------------------------------------------------------------------
// Helper — Build full quote detail with line items
// ---------------------------------------------------------------------------

async function getQuoteDetail(quoteId: string): Promise<QuoteDetail> {
  const [quote] = await db.select().from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  const lineItemsRows = await db
    .select()
    .from(quoteLineItems)
    .where(eq(quoteLineItems.quoteId, quoteId))
    .orderBy(asc(quoteLineItems.id))

  return {
    id: quote.id,
    quoteNumber: quote.quoteNumber,
    customerId: quote.customerId,
    status: quote.status as QuoteStatus,
    notes: quote.notes,
    lineItems: lineItemsRows.map(row => ({
      ...row,
      createdAt: row.createdAt.getTime(),
    })) as QuoteLineItem[],
    createdAt: quote.createdAt.getTime(),
    updatedAt: quote.updatedAt.getTime(),
  }
}

import { Hono } from 'hono'
import {
  createQuote,
  getQuotesList,
  getQuoteById,
  updateQuote,
  deleteQuote,
  createQuoteLineItem,
  updateQuoteLineItem,
  deleteQuoteLineItem,
  type QuoteDetail,
} from '../services/quote.service.js'

const quotesRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /quotes — List quotes with optional status filter
// ---------------------------------------------------------------------------

quotesRoutes.get('/', async (c) => {
  const statusFilter = c.req.query('status') as string | undefined

  try {
    const result = await getQuotesList(statusFilter)
    return c.json(result)
  } catch (err) {
    console.error('[GET /quotes] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// GET /quotes/:id — Get quote detail with line items
// ---------------------------------------------------------------------------

quotesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const quote = await getQuoteById(id)
    return c.json(quote as QuoteDetail)
  } catch (err) {
    if (err instanceof Error && err.name === 'QuoteNotFoundError') {
      return c.json({ error: 'Quote not found', code: 'NOT_FOUND' }, 404)
    }

    console.error('[GET /quotes/:id] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /quotes — Create a new draft quote
// ---------------------------------------------------------------------------

quotesRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    // Validate required fields
    if (!input || typeof input !== 'object') {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const quote = await createQuote({
      customerId: input.customerId ?? null,
      notes: input.notes ?? null,
    })

    return c.json(quote as QuoteDetail, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to create quote'
    console.error('[POST /quotes] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /quotes/:id — Update draft fields only (customerId, notes)
// Draft-only enforcement: returns 403 if quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    // Validate request body
    if (!input || typeof input !== 'object') {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const quote = await updateQuote(id, {
      customerId: input.customerId ?? undefined,
      notes: input.notes ?? undefined,
    })

    return c.json(quote as QuoteDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Update failed'
    const name = (err as { name?: string }).name || ''

    if (name === 'QuoteNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    if (name === 'QuoteNotDraftError') {
      return c.json({ error: message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    console.error('[PATCH /quotes/:id] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// DELETE /quotes/:id — Delete draft quote only
// Draft-only enforcement: returns 403 if quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.delete('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    await deleteQuote(id)
    return c.json({ message: 'Quote deleted successfully' })
  } catch (err) {
    if (err instanceof Error && err.name === 'QuoteNotFoundError') {
      return c.json({ error: 'Quote not found', code: 'NOT_FOUND' }, 404)
    }

    if (err instanceof Error && err.name === 'QuoteNotDraftError') {
      return c.json({ error: err.message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    const message = err instanceof Error ? err.message : 'Delete failed'
    console.error('[DELETE /quotes/:id] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /quotes/:quoteId/lines — Add line item to a quote
// Draft-only enforcement: returns 403 if parent quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.post('/:quoteId/lines', async (c) => {
  const quoteId = c.req.param('quoteId')
  const input = await c.req.json()

  try {
    // Validate request body
    if (!input || typeof input !== 'object' || !input.lineType) {
      return c.json({ error: 'Invalid request body — lineType is required', code: 'VALIDATION_ERROR' }, 400)
    }

    const lineItem = await createQuoteLineItem(quoteId, input as any)

    return c.json(lineItem, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to create line item'
    const name = (err as { name?: string }).name || ''

    if (name === 'QuoteNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    if (name === 'QuoteNotDraftError') {
      return c.json({ error: message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    console.error('[POST /quotes/:quoteId/lines] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /quotes/:quoteId/lines/:lineId — Update a line item
// Draft-only enforcement: returns 403 if parent quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.patch('/:quoteId/lines/:lineId', async (c) => {
  const quoteId = c.req.param('quoteId')
  const lineId = c.req.param('lineId')
  const input = await c.req.json()

  try {
    // Validate request body
    if (!input || typeof input !== 'object' || !input.lineType) {
      return c.json({ error: 'Invalid request body — lineType is required', code: 'VALIDATION_ERROR' }, 400)
    }

    const lineItem = await updateQuoteLineItem(quoteId, lineId, input as any)

    return c.json(lineItem)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to update line item'
    const name = (err as { name?: string }).name || ''

    if (name === 'QuoteNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    if (name === 'QuoteNotDraftError') {
      return c.json({ error: message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    if (name === 'QuoteLineItemNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    console.error('[PATCH /quotes/:quoteId/lines/:lineId] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// DELETE /quotes/:quoteId/lines/:lineId — Delete a line item
// Draft-only enforcement: returns 403 if parent quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.delete('/:quoteId/lines/:lineId', async (c) => {
  const quoteId = c.req.param('quoteId')
  const lineId = c.req.param('lineId')

  try {
    await deleteQuoteLineItem(quoteId, lineId)
    return c.json({ message: 'Line item deleted successfully' })
  } catch (err) {
    if (err instanceof Error && err.name === 'QuoteNotFoundError') {
      return c.json({ error: 'Quote not found', code: 'NOT_FOUND' }, 404)
    }

    if (err instanceof Error && err.name === 'QuoteNotDraftError') {
      return c.json({ error: err.message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    if (err instanceof Error && err.name === 'QuoteLineItemNotFoundError') {
      return c.json({ error: 'Line item not found', code: 'NOT_FOUND' }, 404)
    }

    const message = err instanceof Error ? err.message : 'Delete failed'
    console.error('[DELETE /quotes/:quoteId/lines/:lineId] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

