/**
 * Quote feature types — mirrors API response shapes for frontend use.
 */

// ============================================================================
// Quote Status
// ============================================================================

export type QuoteStatus = 'draft' | 'sent' | 'converted' | 'rejected'

/** Color mapping for status badges */
export const QUOTE_STATUS_COLORS: Record<QuoteStatus, string> = {
  draft: 'bg-blue-100 text-blue-800',
  sent: 'bg-yellow-100 text-yellow-800',
  converted: 'bg-green-100 text-green-800',
  rejected: 'bg-red-100 text-red-800',
}

// ============================================================================
// Line Item Type
// ============================================================================

export type QuoteLineItemType = 'part' | 'labor' | 'bicycle'

/** Label for each line item type */
export const LINE_TYPE_LABELS: Record<QuoteLineItemType, string> = {
  part: 'Part',
  labor: 'Labor',
  bicycle: 'Bicycle',
}

// ============================================================================
// Quote Detail Shape (matches API response)
// ============================================================================

export interface QuoteDetail {
  id: string
  quoteNumber: string
  customerId: string | null
  status: QuoteStatus
  notes: string | null
  lineItems: QuoteLineItem[]
  createdAt: number
  updatedAt: number
}

/** Compact quote shape for list display */
export interface QuoteListItem {
  id: string
  quoteNumber: string
  customerId: string | null
  status: QuoteStatus
  notes: string | null
  createdAt: number
  updatedAt: number
}

// ============================================================================
// Quote Line Item Shape
// ============================================================================

export interface QuoteLineItem {
  id: string
  quoteId: string
  lineType: QuoteLineItemType
  partId: string | null
  laborServiceId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
  bicycleId: string | null
  bicycleBrand: string | null
  bicycleModel: string | null
  bicycleYear: number | null
  bicycleColor: string | null
  bicycleFrameSize: string | null
  createdAt: number
}

// ============================================================================
// Customer Shape (for selection in forms)
// ============================================================================

export interface QuoteCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

// ============================================================================
// Create Quote Form Data
// ============================================================================

/** Form data for creating a new quote */
export interface CreateQuoteFormData {
  customerId: string | null
  notes: string
}

/** Default empty form state */
export const createEmptyQuoteForm = (): CreateQuoteFormData => ({
  customerId: null,
  notes: '',
})

// ============================================================================
// Line Item Form Data
// ============================================================================

/** Form data for creating a part line item */
export interface CreatePartLineItemData {
  lineType: 'part'
  partId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
}

/** Form data for creating a labor line item */
export interface CreateLaborLineItemData {
  lineType: 'labor'
  laborServiceId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
}

/** Form data for creating a bicycle line item */
export interface CreateBicycleLineItemData {
  lineType: 'bicycle'
  bicycleId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
  bicycleBrand: string | null
  bicycleModel: string | null
  bicycleYear: number | null
  bicycleColor: string | null
  bicycleFrameSize: string | null
}

/** Union type for creating a line item */
export type CreateLineItemData =
  | CreatePartLineItemData
  | CreateLaborLineItemData
  | CreateBicycleLineItemData

// ============================================================================
// Stock Warning — used to indicate low-stock parts on line items
// ============================================================================

/** Threshold (in units) below which a part shows a stock warning */
export const STOCK_WARNING_THRESHOLD = 5

/**
 * Quote feature API client.
 */

import type {
  QuoteDetail,
  QuoteListItem,
  QuoteLineItem,
  CreateQuoteFormData,
  CreateLineItemData,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface QuotesListResponse {
  quotes: QuoteListItem[]
  total: number
}

interface UpdateQuoteInput {
  customerId?: string | null
  notes?: string
}

interface UpdateLineItemInput {
  lineType: 'part' | 'labor' | 'bicycle'
  description?: string
  quantity?: number
  unitPriceNet?: number
  vatRateId?: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}

// ---------------------------------------------------------------------------
// API Functions — Quote CRUD
// ---------------------------------------------------------------------------

/** Get paginated quote list with optional status filter. */
export async function getQuotes(statusFilter?: string): Promise<QuotesListResponse> {
  const params = new URLSearchParams()
  if (statusFilter) params.set('status', statusFilter)

  const response = await fetch(`/api/quotes?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch quotes list')
  }

  return response.json()
}

/** Get a single quote by ID with line items. */
export async function getQuote(id: string): Promise<QuoteDetail> {
  const response = await fetch(`/api/quotes/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch quote')
  }

  return response.json()
}

/** Create a new draft quote. */
export async function createQuote(input: CreateQuoteFormData): Promise<QuoteDetail> {
  const response = await fetch('/api/quotes', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      customerId: input.customerId,
      notes: input.notes || null,
    }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create quote' }))
    throw new Error(error.error || 'Failed to create quote')
  }

  return response.json()
}

/** Update a draft quote's fields. */
export async function updateQuote(id: string, input: UpdateQuoteInput): Promise<QuoteDetail> {
  const response = await fetch(`/api/quotes/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      ...(input.customerId !== undefined && { customerId: input.customerId }),
      ...(input.notes !== undefined && { notes: input.notes || null }),
    }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update quote' }))
    throw new Error(error.error || 'Failed to update quote')
  }

  return response.json()
}

/** Delete a draft quote. */
export async function deleteQuote(id: string): Promise<void> {
  const response = await fetch(`/api/quotes/${id}`, {
    method: 'DELETE',
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to delete quote' }))
    throw new Error(error.error || 'Failed to delete quote')
  }
}

