/**
 * Quotes Page — List view with status filter and "New Quote" button.
 */

import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { Plus, Filter, Eye } from 'lucide-react'
import {
  QUOTE_STATUS_COLORS,
  type QuoteStatus,
  type QuoteListItem,
} from './types.js'
import { getQuotes } from './api.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface QuotesListResponse {
  quotes: QuoteListItem[]
  total: number
}

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: QuoteStatus }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${QUOTE_STATUS_COLORS[status]}`}>
      {status}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Customer Name Helper
// ---------------------------------------------------------------------------

function getCustomerName(customerId: string | null): string {
  if (!customerId) return '—'
  // In production, this would fetch customer details from the API.
  // For now, show a truncated ID as placeholder.
  return `Customer ${customerId.slice(0, 8)}...`
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number): string {
  const d = new Date(epochMs)
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
}

// ---------------------------------------------------------------------------
// Component — Quotes Page
// ---------------------------------------------------------------------------

export function QuotesPage() {
  const navigate = useNavigate()
  const [quotes, setQuotes] = useState<QuoteListItem[]>([])
  const [totalPages, setTotalPages] = useState(1)
  const [currentPage, setCurrentPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [statusFilter, setStatusFilter] = useState<QuoteStatus | ''>('')

  // Fetch quotes list
  const fetchQuotes = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const data: QuotesListResponse = await getQuotes(statusFilter || undefined)
      setQuotes(data.quotes)
      setTotalPages(Math.ceil(data.total / 20))
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load quotes')
    } finally {
      setLoading(false)
    }
  }, [statusFilter])

  useEffect(() => {
    fetchQuotes()
  }, [fetchQuotes, currentPage])

  // Handle "New Quote" button click
  const handleNewQuote = () => {
    navigate('/quotes/new')
  }

  // Handle row click to view detail
  const handleViewQuote = (id: string) => {
    navigate(`/quotes/${id}`)
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-gray-900">Quotes</h1>
        <button
          onClick={handleNewQuote}
          className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
        >
          <Plus className="h-4 w-4" />
          New Quote
        </button>
      </div>

      {/* Filters */}
      <div className="flex items-center gap-3">
        <Filter className="h-4 w-4 text-gray-400" />
        <select
          value={statusFilter}
          onChange={(e) => {
            setStatusFilter(e.target.value as QuoteStatus | '')
            setCurrentPage(1)
          }}
          className="rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
        >
          <option value="">All Statuses</option>
          <option value="draft">Draft</option>
          <option value="sent">Sent</option>
          <option value="converted">Converted</option>
          <option value="rejected">Rejected</option>
        </select>
      </div>

      {/* Error State */}
      {error && (
        <div className="rounded-lg bg-red-50 p-4 text-sm text-red-700">
          {error}
        </div>
      )}

      {/* Loading State */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <div className="h-6 w-6 animate-spin rounded-full border-2 border-blue-600 border-t-transparent" />
        </div>
      ) : quotes.length === 0 ? (
        /* Empty State */
        <div className="rounded-lg border border-dashed border-gray-300 p-12 text-center">
          <p className="text-sm text-gray-500">No quotes found</p>
          <button
            onClick={handleNewQuote}
            className="mt-3 inline-flex items-center gap-2 text-sm font-medium text-blue-600 hover:text-blue-700"
          >
            <Plus className="h-4 w-4" />
            Create your first quote
          </button>
        </div>
      ) : (
        /* Quotes Table */
        <div className="overflow-hidden rounded-lg border border-gray-200 bg-white shadow-sm">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Quote #</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Status</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Customer</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Created</th>
                <th className="px-4 py-3 text-right text-xs font-medium uppercase tracking-wide text-gray-500">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {quotes.map((quote) => (
                <tr key={quote.id} className="hover:bg-gray-50">
                  <td className="whitespace-nowrap px-4 py-3 text-sm font-medium text-gray-900">
                    {quote.quoteNumber}
                  </td>
                  <td className="whitespace-nowrap px-4 py-3">
                    <StatusBadge status={quote.status} />
                  </td>
                  <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-500">
                    {getCustomerName(quote.customerId)}
                  </td>
                  <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-500">
                    {formatDate(quote.createdAt)}
                  </td>
                  <td className="whitespace-nowrap px-4 py-3 text-right text-sm">
                    <button
                      onClick={() => handleViewQuote(quote.id)}
                      disabled={quote.status !== 'draft'}
                      className={`inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium ${
                        quote.status === 'draft'
                          ? 'text-blue-600 hover:bg-blue-50'
                          : 'text-gray-400 cursor-not-allowed'
                      }`}
                    >
                      <Eye className="h-3 w-3" />
                      View
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-gray-500">
            Page {currentPage} of {totalPages}
          </p>
          <div className="flex gap-2">
            <button
              onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
              disabled={currentPage === 1}
              className="rounded-md border border-gray-300 px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
            >
              Previous
            </button>
            <button
              onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
              disabled={currentPage === totalPages}
              className="rounded-md border border-gray-300 px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * Create Quote Form — Dialog for creating a new draft quote.
 */

import { useState, useEffect } from 'react'
import { X, User, Building2, Phone, Mail } from 'lucide-react'
import type { CreateQuoteFormData } from '../types.js'
import { createEmptyQuoteForm } from '../types.js'
import { createQuote } from '../api.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface QuoteCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

interface CreateQuoteDialogProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: (quoteId: string) => void
}

// ---------------------------------------------------------------------------
// Component — Customer Selector
// ---------------------------------------------------------------------------

function CustomerSelector({
  selectedCustomerId,
  onSelect,
}: {
  selectedCustomerId: string | null
  onSelect: (customerId: string | null) => void
}) {
  const [customers, setCustomers] = useState<QuoteCustomer[]>([])
  const [searchTerm, setSearchTerm] = useState('')
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (!isOpen) return

    async function fetchCustomers() {
      setLoading(true)
      try {
        // Fetch customers from API with optional search filter
        const params = new URLSearchParams({ limit: '50' })
        if (searchTerm) params.set('search', searchTerm)

        const response = await fetch(`/api/customers?${params.toString()}`)
        if (!response.ok) throw new Error('Failed to fetch customers')

        const data = await response.json() as { items: QuoteCustomer[]; total: number }
        setCustomers(data.items ?? [])
      } catch (err) {
        console.error('[CreateQuoteForm] Failed to load customers:', err)
        setCustomers([])
      } finally {
        setLoading(false)
      }
    }

    fetchCustomers()
  }, [searchTerm]) // Re-fetch when search term changes

  return (
    <div className="space-y-2">
      <label className="block text-sm font-medium text-gray-700">Customer</label>

      {/* Search */}
      <input
        type="text"
        placeholder="Search customers..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
      />

      {/* Customer List */}
      {loading ? (
        <div className="flex items-center justify-center py-4">
          <div className="h-4 w-4 animate-spin rounded-full border-2 border-blue-600 border-t-transparent" />
        </div>
      ) : customers.length === 0 && searchTerm ? (
        <p className="py-2 text-sm text-gray-500">No customers found</p>
      ) : (
        <div className="max-h-48 overflow-y-auto rounded-lg border border-gray-200">
          {customers.map((customer) => (
            <button
              key={customer.id}
              onClick={() => {
                onSelect(customer.id)
                setSearchTerm('')
              }}
              className={`flex w-full items-center gap-3 px-3 py-2 text-left text-sm hover:bg-gray-50 ${
                selectedCustomerId === customer.id ? 'bg-blue-50' : ''
              }`}
            >
              {customer.type === 'company' ? (
                <Building2 className="h-4 w-4 flex-shrink-0 text-gray-400" />
              ) : (
                <User className="h-4 w-4 flex-shrink-0 text-gray-400" />
              )}
              <div className="min-w-0">
                <p className="truncate font-medium text-gray-900">{customer.displayName}</p>
                <p className="text-xs text-gray-500 capitalize">{customer.type}</p>
              </div>
            </button>
          ))}

          {/* Clear selection */}
          {selectedCustomerId && (
            <button
              onClick={() => onSelect(null)}
              className="flex w-full items-center gap-3 px-3 py-2 text-left text-sm font-medium text-red-600 hover:bg-red-50"
            >
              <X className="h-4 w-4 flex-shrink-0" />
              None (walk-in)
            </button>
          )}
        </div>
      )}

      {selectedCustomerId && (
        <p className="text-xs text-gray-500">Selected customer will be linked to this quote</p>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Component — Create Quote Dialog
// ---------------------------------------------------------------------------

export function CreateQuoteDialog({ isOpen, onClose, onSuccess }: CreateQuoteDialogProps) {
  const [formData, setFormData] = useState<CreateQuoteFormData>(createEmptyQuoteForm())
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Reset form when dialog opens
  useEffect(() => {
    if (isOpen) {
      setFormData(createEmptyQuoteForm())
      setError(null)
    }
  }, [isOpen])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)

    try {
      const quote = await createQuote(formData)
      onSuccess(quote.id)
      onClose()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create quote')
    } finally {
      setSubmitting(false)
    }
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />

      {/* Dialog */}
      <div className="relative w-full max-w-lg rounded-xl bg-white p-6 shadow-xl">
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold text-gray-900">New Quote</h2>
          <button
            onClick={onClose}
            className="rounded-md p-1 text-gray-400 hover:bg-gray-100 hover:text-gray-600"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <div className="rounded-lg bg-red-50 p-3 text-sm text-red-700">{error}</div>
          )}

          <CustomerSelector
            selectedCustomerId={formData.customerId}
            onSelect={(customerId) => setFormData(prev => ({ ...prev, customerId }))}
          />

          {/* Notes */}
          <div className="space-y-2">
            <label htmlFor="notes" className="block text-sm font-medium text-gray-700">
              Notes (optional)
            </label>
            <textarea
              id="notes"
              rows={3}
              value={formData.notes}
              onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
              placeholder="Internal notes about this quote..."
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 resize-none"
            />
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              disabled={submitting}
              className="rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {submitting ? 'Creating...' : 'Create Quote'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

/**
