  type QuoteDetail,
  type QuoteLineItem,
  type CreateLineItemData,
} from '../types.js'
import { getQuote, updateQuote, deleteQuote, createQuoteLineItem, updateQuoteLineItem, deleteQuoteLineItem } from '../api.js'
import { formatCentsToEuro } from '@shared/lib/utils.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface QuoteDetailPanelProps {
  quoteId: string
}

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: string }) {
  const colorClass = QUOTE_STATUS_COLORS[status as keyof typeof QUOTE_STATUS_COLORS] || 'bg-gray-100 text-gray-800'
  return (
