// ---------------------------------------------------------------------------
// Component — Stock Warning Indicator
// ---------------------------------------------------------------------------

function StockWarning({ partId }: { partId: string | null }) {
  if (!partId) return null

  // In production, this would check stock levels from the API.
  // For now, we show a placeholder warning for demonstration.
  return (
    <span className="inline-flex items-center gap-1 text-xs text-orange-600">
